fn get_min_val(a: &Vec<i8>) -> i8 {
    debug_assert!(!a.is_empty());
    let mut min_v = a[0];
    for &x in a.iter().skip(1) {
        if x < min_v {
            min_v = x;
        }
    }
    min_v
}

fn get_max_val(a: &Vec<i8>) -> i8 {
    debug_assert!(!a.is_empty());
    let mut max_v = a[0];
    for &x in a.iter().skip(1) {
        if x > max_v {
            max_v = x;
        }
    }
    max_v
}

/// Returns a value bounded by the array's min/max, with:
/// - q == 0  => min element
/// - q == 100 => max element
///
/// For intermediate q, this implements a simple discrete quantile:
/// sort ascending and pick index floor(q*(n-1)/100).
fn nanquantile(a: Vec<i8>, q: i8) -> i8 {
    debug_assert!(!a.is_empty());
    debug_assert!((0..=100).contains(&q));

    if q == 0 {
        return get_min_val(&a);
    }
    if q == 100 {
        return get_max_val(&a);
    }

    let mut v = a;
    v.sort_unstable();

    let n = v.len();
    // q in 1..=99, n >= 1, so n-1 is safe.
    let idx = (q as usize) * (n - 1) / 100;
    v[idx]
}